mapper.sql:
WHERE employees.is_active = 1
AND employees.department_id = #{filter.departmentId}
AND EXISTS (SELECT 1 FROM employee_egroups WHERE employee_egroups.employee_id = employees.id AND employee_egroups.egroup_id = #{filter.groupId})
AND employees.employee_status_id = #{filter.statusId}
AND MONTH(employees.created) = MONTH(#{filter.dateOfWork}) AND YEAR(employees.created) = YEAR(#{filter.dateOfWork})
AND ( employees.name LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.name_kh LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.code LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.telephone LIKE CONCAT("%", #{filter.searchText}, "%") OR employees.personal_number LIKE CONCAT("%", #{filter.searchText}, "%") )

