ORDER BY
${filter.orderBy}
employees.id DESC
LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM employees
WHERE is_active = 1 AND name = #{name} AND name_kh = #{nameKh} AND id_card = #{idCard}
 AND id != #{id}

