UPDATE employee_apply_status SET
date = #{date},
date_to = #{dateTo}
WHERE employee_id = #{employeesId} ORDER BY id DESC LIMIT 1;

UPDATE employee_apply_types SET
employee_type_id = #{applyEmployeeTypesRequest.employeeTypeId},
date_from = #{applyEmployeeTypesRequest.dateFrom},
date_to = #{applyEmployeeTypesRequest.dateTo}
WHERE is_active = 1 AND employee_id = #{applyEmployeeTypesRequest.employeeId} AND employee_type_id = #{applyEmployeeTypesRequest.employeeTypeId} ORDER BY id DESC LIMIT 1;

