UPDATE employees SET
                   current_salary = #{employeesIncreaseSalary.currentSalary},
                   modified = NOW(),
                   modified_by = #{employeesIncreaseSalary.modifiedBy}
WHERE id = #{employeesIncreaseSalary.employeeId};

UPDATE employee_increase_salaries SET
  increase_salary = #{employeesIncreaseSalary.increaseSalary}
WHERE employee_id = #{employeesIncreaseSalary.employeeId} AND date = #{employeesIncreaseSalary.date};

mapper.select:
SELECT employee_increase_salaries.*, employee_increase_salaries.employee_id AS employeeId, employee_increase_salaries.increase_salary AS increaseSalary, employees.name_kh AS nameKh, employees.name AS nameEn FROM employee_increase_salaries LEFT JOIN employees ON employees.id = employee_increase_salaries.employee_id WHERE employee_increase_salaries.is_active = 1
AND employee_increase_salaries.employee_id = #{filter.employeesId}
AND employee_increase_salaries.date = #{filter.date}

